import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('escalando-los-muros', 'C',
 [dict(t=1397, e=1450, titulo='Un muro que te detiene', txt='Un muro es algo que te pone un límite. Yo quiero verlo en este momento como aquello que puede traer oposición a tu vida. Habrá algo que tú vas campeón, hermano, que tú vas adelante y de repente topas con un muro que no te deja seguir adelante. Pues esta mañana, en el nombre de Jesús, Dios te va a hacer que lo puedas escalar. Vamos a romper, hermano amado, con todo aquello que detiene nuestro caminar, sea lo que sea.'),
  dict(t=2905, e=2945, titulo='Muros ancestrales', txt='Y esos son problemas ancestrales que podemos traer en nuestra vida, y nosotros tenemos la capacidad de escalar ese muro y decir: «Esto aquí termina. No lo quiero ni para mi vida, ni lo quiero para los míos».'),
  dict(t=3936, e=3992, titulo='El pecado oculto', txt='La gente, cuando piensa en pecado oculto, solo piensa en […]. Pero, si no estoy mal, la murmuración también es pecado. Y es de los pecados más ocultos que hay, a veces, porque normalmente el murmurador no dice las cosas en público; las dice así. Es un pecado oculto. Pero yo no te estoy hablando de algo específico. Eso cada quien tiene que examinar su corazón.')],
 [dict(t=435, txt='Todos vamos en esa luz que debe ir progresiva en nuestro corazón. […] En mi corazón pueden haber todavía tinieblas.'),
  dict(t=2755, txt='Hay gente que no puede dejar ciertos hábitos porque tal vez en su corazón ancestralmente se lo heredaron.'),
  dict(t=5005, txt='Si alguien quiere recibir al Señor en su corazón o alguien quiere reconciliar, este es el momento para poder entregarle su vida al Señor.')],
 ['¿Qué «muro» te ha detenido últimamente, y qué parte de él depende de ti derribar con la ayuda de Dios?',
  '¿Hay un hábito o una costumbre que viene de tu familia y que hoy quieres decir: «Esto aquí termina»?',
  'Sin señalar a nadie, ¿qué pecado «escondido» te pediría Dios que examines esta semana en tu corazón?'])
